    half_turn = rotate_cw(rotate_cw(original))
    counterclockwise = rotate_cw(half_turn)
    return [
        left + right
        for top, bottom in ((original, clockwise), (counterclockwise, half_turn))
        for left, right in zip(top, bottom)
